'use client';

import { useEffect } from 'react';

const GlobalCursorGlow = () => {
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      // Set global CSS custom properties on document root for high-performance rendering
      document.documentElement.style.setProperty('--global-mouse-x', `${e.clientX}px`);
      document.documentElement.style.setProperty('--global-mouse-y', `${e.clientY}px`);
    };

    window.addEventListener('mousemove', handleMouseMove);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
    };
  }, []);

  return <div className="global-cursor-glow" aria-hidden="true" />;
};

export default GlobalCursorGlow;
