'use client';

import Link from 'next/link';
import { useState, useEffect, useRef } from 'react';
import portfolioData from '@/data/portfolio.json';
import Logo from './Logo';

const Navbar = () => {
  const [menuOpen, setMenuOpen] = useState(false);
  const [isVisible, setIsVisible] = useState(false);
  const [timeStr, setTimeStr] = useState('');
  const navRef = useRef<HTMLElement>(null);
  
  // Dynamic Local Clock for Bangalore, India
  useEffect(() => {
    const updateTime = () => {
      const options: Intl.DateTimeFormatOptions = {
        timeZone: 'Asia/Kolkata',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: true
      };
      const formatter = new Intl.DateTimeFormat([], options);
      setTimeStr(formatter.format(new Date()));
    };
    
    updateTime();
    const interval = setInterval(updateTime, 1000);
    return () => clearInterval(interval);
  }, []);

  // Handle initial appearance with animation
  useEffect(() => {
    const timer = setTimeout(() => {
      setIsVisible(true);
    }, 4400); // Synchronize with page content reveal (starts at 4.2s)
    
    return () => clearTimeout(timer);
  }, []);
  
  // Lock body scroll when mobile menu is open
  useEffect(() => {
    if (menuOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
    return () => {
      document.body.style.overflow = '';
    };
  }, [menuOpen]);

  const toggleMenu = () => {
    setMenuOpen(!menuOpen);
  };
  
  return (
    <>
      {/* Unified Apple-Style Full-Width Navbar */}
      <header 
        ref={navRef}
        className={`navbar ${isVisible ? 'nav-visible' : ''}`}
        style={{
          WebkitBackdropFilter: 'saturate(180%) blur(20px)',
          backdropFilter: 'saturate(180%) blur(20px)',
        }}
      >
        <div className="max-w-5xl w-full h-full flex justify-between items-center px-6 mx-auto">
          {/* Logo on the left */}
          <Link href="/" className="nav-logo flex items-center select-none" aria-label="Arshad Barves Logo" onClick={() => setMenuOpen(false)}>
            <Logo size={22} />
          </Link>
          
          {/* Desktop Navigation Links in the Center */}
          <nav className="nav-links hidden md:flex items-center gap-8">
            <Link href="#home" className="text-[12px] font-normal tracking-wide text-white/80 hover:text-white transition-colors duration-200">home</Link>
            <Link href="#about" className="text-[12px] font-normal tracking-wide text-white/80 hover:text-white transition-colors duration-200">about</Link>
            <Link href="#projects" className="text-[12px] font-normal tracking-wide text-white/80 hover:text-white transition-colors duration-200">projects</Link>
            <Link href="#experience" className="text-[12px] font-normal tracking-wide text-white/80 hover:text-white transition-colors duration-200">experience</Link>
            <Link href="#contact" className="text-[12px] font-normal tracking-wide text-white/80 hover:text-white transition-colors duration-200">contact</Link>
          </nav>
            
          {/* Desktop status bar on the right */}
          <div className="hidden md:flex items-center gap-2 px-3 py-0.5 bg-neutral-900/60 border border-white/5 rounded-full">
            <span className="inline-block w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></span>
            <span className="text-[8px] uppercase tracking-wider text-neutral-400 font-mono">
              {portfolioData.personal.location} / {timeStr}
            </span>
          </div>

          {/* Mobile Menu Toggle Button on the right */}
          <button 
            className="block md:hidden text-white/80 hover:text-white transition-all duration-300 w-10 h-10 flex items-center justify-center -mr-2 relative z-50 rounded-full active:bg-white/5"
            onClick={toggleMenu}
            aria-label="Toggle menu"
          >
            <div className="w-[18px] h-2.5 flex flex-col justify-between items-center relative">
              <span className={`w-full h-0.5 bg-current rounded-full transition-all duration-300 transform ${menuOpen ? 'rotate-45 translate-y-[4px]' : ''}`} />
              <span className={`w-full h-0.5 bg-current rounded-full transition-all duration-300 ${menuOpen ? 'opacity-0 scale-x-0' : ''}`} />
              <span className={`w-full h-0.5 bg-current rounded-full transition-all duration-300 transform ${menuOpen ? '-rotate-45 -translate-y-[4px]' : ''}`} />
            </div>
          </button>
        </div>
      </header>

      {/* Mobile Full-Screen Overlay Navigation Menu (iOS Slide-down style) */}
      <div 
        className={`fixed inset-x-0 bottom-0 bg-[#0f0f11]/98 z-40 md:hidden flex flex-col justify-between p-8 pt-16 transition-all duration-500 ease-in-out ${
          menuOpen ? 'top-11 opacity-100 pointer-events-auto' : 'top-[-100%] opacity-0 pointer-events-none'
        }`}
        style={{
          WebkitBackdropFilter: 'saturate(200%) blur(24px)',
          backdropFilter: 'saturate(200%) blur(24px)',
        }}
      >
        {menuOpen && (
          <>
            {/* Navigation links stack with staggered fade-in */}
            <nav className="flex flex-col gap-6 mt-6">
              <Link 
                href="#home" 
                className="mobile-nav-link" 
                style={{ animationDelay: '0.08s' }} 
                onClick={() => setMenuOpen(false)}
              >
                home
              </Link>
              <Link 
                href="#about" 
                className="mobile-nav-link" 
                style={{ animationDelay: '0.14s' }} 
                onClick={() => setMenuOpen(false)}
              >
                about
              </Link>
              <Link 
                href="#projects" 
                className="mobile-nav-link" 
                style={{ animationDelay: '0.2s' }} 
                onClick={() => setMenuOpen(false)}
              >
                projects
              </Link>
              <Link 
                href="#experience" 
                className="mobile-nav-link" 
                style={{ animationDelay: '0.26s' }} 
                onClick={() => setMenuOpen(false)}
              >
                experience
              </Link>
              <Link 
                href="#contact" 
                className="mobile-nav-link" 
                style={{ animationDelay: '0.32s' }} 
                onClick={() => setMenuOpen(false)}
              >
                contact
              </Link>
            </nav>

            {/* Mobile Footer area inside drawer */}
            <div className="flex flex-col gap-4 border-t border-white/5 pt-6 pb-2 animate-[slide-in-fade_0.5s_ease_forwards]" style={{ animationDelay: '0.38s', opacity: 0 }}>
              <div className="flex justify-between items-center">
                <span className="text-[9px] uppercase tracking-widest text-neutral-500 font-mono">Location</span>
                <span className="text-[9px] uppercase tracking-widest text-neutral-300 font-mono">{portfolioData.personal.location}</span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-[9px] uppercase tracking-widest text-neutral-500 font-mono">Local Time</span>
                <span className="text-[9px] uppercase tracking-widest text-neutral-300 font-mono">{timeStr}</span>
              </div>
              <div className="flex justify-between items-center mt-2">
                <span className="text-[9px] uppercase tracking-widest text-neutral-500 font-mono">Connect</span>
                <div className="flex gap-4">
                  <a href="https://github.com/arshadbarves" target="_blank" rel="noopener noreferrer" className="text-xs text-neutral-400 hover:text-white transition-colors">GitHub</a>
                  <a href="https://www.linkedin.com/in/arshadbarves" target="_blank" rel="noopener noreferrer" className="text-xs text-neutral-400 hover:text-white transition-colors">LinkedIn</a>
                </div>
              </div>
            </div>
          </>
        )}
      </div>
    </>
  );
};

export default Navbar;
