'use client';

import { createContext, useContext, useEffect, useState } from 'react';
import { ThemeAccent, ThemeConfig, ThemeMode } from '../utils/theme';

type ThemeContextType = {
  theme: ThemeConfig;
  setTheme: (theme: Partial<ThemeConfig>) => void;
};

const initialTheme: ThemeConfig = {
  mode: 'dark',
  accent: 'blue'
};

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

export function ThemeProvider({ children }: { children: React.ReactNode }) {
  const [theme, setThemeState] = useState<ThemeConfig>(initialTheme);
  
  // Load theme from localStorage on client
  useEffect(() => {
    const savedTheme = localStorage.getItem('portfolio-theme');
    if (savedTheme) {
      try {
        const parsedTheme = JSON.parse(savedTheme);
        setThemeState(parsedTheme);
      } catch (e) {
        console.error('Failed to parse saved theme');
      }
    }
    
    // Apply theme to document
    updateThemeClasses(theme);
  }, []);
  
  // Update theme in localStorage and apply classes
  const setTheme = (newTheme: Partial<ThemeConfig>) => {
    const updatedTheme = { ...theme, ...newTheme };
    setThemeState(updatedTheme);
    localStorage.setItem('portfolio-theme', JSON.stringify(updatedTheme));
    updateThemeClasses(updatedTheme);
  };
  
  // Update CSS classes based on theme
  const updateThemeClasses = (themeConfig: ThemeConfig) => {
    const root = document.documentElement;
    
    // Remove existing theme classes
    root.classList.remove('theme-light', 'theme-dark');
    root.classList.remove('accent-blue', 'accent-purple', 'accent-rose');
    
    // Add new theme classes
    root.classList.add(`theme-${themeConfig.mode}`);
    root.classList.add(`accent-${themeConfig.accent}`);
    
    // If system preference, watch for changes
    if (themeConfig.mode === 'system') {
      const prefersDark = window.matchMedia('(prefers-color-scheme: dark)');
      root.classList.remove('theme-light', 'theme-dark');
      root.classList.add(prefersDark.matches ? 'theme-dark' : 'theme-light');
      
      // Update on system preference change
      const handleChange = (e: MediaQueryListEvent) => {
        root.classList.remove('theme-light', 'theme-dark');
        root.classList.add(e.matches ? 'theme-dark' : 'theme-light');
      };
      
      prefersDark.addEventListener('change', handleChange);
      return () => prefersDark.removeEventListener('change', handleChange);
    }
  };
  
  return (
    <ThemeContext.Provider value={{ theme, setTheme }}>
      {children}
    </ThemeContext.Provider>
  );
}

export function useTheme() {
  const context = useContext(ThemeContext);
  if (context === undefined) {
    // Return a safe fallback instead of throwing to prevent Next.js isolated static page collection crashes
    return {
      theme: initialTheme,
      setTheme: () => {}
    };
  }
  return context;
}
