'use client';

interface LogoProps {
  className?: string;
  size?: number;
  animated?: boolean;
}

const Logo = ({ className = '', size = 36, animated = false }: LogoProps) => {
  const uid = animated ? 'logo-anim' : 'logo-static';
  
  // Optical sizing for sharp, legible rendering at micro sizes (e.g. navbar <= 32px)
  const isSmall = size <= 32;
  
  // Symmetric Monogram Coordinates
  // Large: Arch (M 32 70 L 46 38 Q 50 28 54 38 L 68 70), Cross (M 38 54 L 62 54), stroke=3.5, glow=7
  // Small: Arch (M 26 71 L 44 33 Q 50 24 56 33 L 73 71), Cross (M 34 54 L 66 54), stroke=5.2, glow=8.5
  const archD = isSmall 
    ? "M 26 71 L 44 33 Q 50 24 56 33 L 73 71" 
    : "M 32 70 L 46 38 Q 50 28 54 38 L 68 70";
    
  const crossD = isSmall 
    ? "M 34 54 L 66 54" 
    : "M 38 54 L 62 54";
    
  const strokeWidth = isSmall ? 5.2 : 3.5;
  const glowStrokeWidth = isSmall ? 8.5 : 7;
  const shineStrokeWidth = isSmall ? 5.8 : 3.8;
  const badgeStrokeWidth = isSmall ? 1.8 : 1.5;

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 100 100"
      width={size}
      height={size}
      fill="none"
      className={`${className}`}
      style={{ overflow: 'visible' }}
    >
      <defs>
        {/* Volumetric Badge Background — semi-transparent glassmorphic radial gradient */}
        <radialGradient id={`${uid}-badge-bg`} cx="50%" cy="30%" r="75%">
          <stop offset="0%" stopColor="rgba(30, 30, 35, 0.85)" />
          <stop offset="50%" stopColor="rgba(18, 18, 20, 0.9)" />
          <stop offset="100%" stopColor="rgba(8, 8, 10, 0.95)" />
        </radialGradient>

        {/* Beveled Border Gradient — catches top-left light, shadows bottom-right */}
        <linearGradient id={`${uid}-border`} x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="rgba(255, 255, 255, 0.45)" />
          <stop offset="35%" stopColor="rgba(113, 113, 122, 0.15)" />
          <stop offset="100%" stopColor="rgba(0, 0, 0, 0.7)" />
        </linearGradient>

        {/* Symmetrical Monogram Gradient — polished silver-to-steel metallic look */}
        <linearGradient id={`${uid}-mono`} x1="30%" y1="20%" x2="70%" y2="80%">
          <stop offset="0%" stopColor="#FFFFFF" />
          <stop offset="45%" stopColor="#E4E4E7" />
          <stop offset="100%" stopColor="#52525B" />
        </linearGradient>

        {/* Ambient Backlight/Glow backing the monogram */}
        <radialGradient id={`${uid}-glow`} cx="50%" cy="50%" r="45%">
          <stop offset="0%" stopColor="#FFFFFF" stopOpacity="0.15" />
          <stop offset="100%" stopColor="#FFFFFF" stopOpacity="0" />
        </radialGradient>

        {/* High-Fidelity Diagonal Specular Shimmer Sweep */}
        <linearGradient id={`${uid}-shine`} x1="-150%" y1="-150%" x2="-50%" y2="-50%">
          <stop offset="0%" stopColor="#FFFFFF" stopOpacity="0" />
          <stop offset="42%" stopColor="#FFFFFF" stopOpacity="0" />
          <stop offset="50%" stopColor="#FFFFFF" stopOpacity="0.85" />
          <stop offset="58%" stopColor="#FFFFFF" stopOpacity="0" />
          <stop offset="100%" stopColor="#FFFFFF" stopOpacity="0" />
          {animated && (
            <>
              <animate attributeName="x1" from="-150%" to="150%" dur="2.4s" begin="1.8s" fill="freeze" repeatCount="1" />
              <animate attributeName="y1" from="-150%" to="150%" dur="2.4s" begin="1.8s" fill="freeze" repeatCount="1" />
              <animate attributeName="x2" from="-50%" to="250%" dur="2.4s" begin="1.8s" fill="freeze" repeatCount="1" />
              <animate attributeName="y2" from="-50%" to="250%" dur="2.4s" begin="1.8s" fill="freeze" repeatCount="1" />
            </>
          )}
        </linearGradient>
      </defs>

      {/* 1. Soft Ambient backing glow */}
      <circle cx="50" cy="50" r="35" fill={`url(#${uid}-glow)`} />

      {/* 2. Premium Squircle Badge Container */}
      <rect
        x="8" y="8"
        width="84" height="84"
        rx="26"
        fill={`url(#${uid}-badge-bg)`}
        stroke={`url(#${uid}-border)`}
        strokeWidth={badgeStrokeWidth}
        className={animated ? 'logo-rect-glow' : ''}
      />

      {/* 3. Underlayer: Wide Ambient Specular Glow (Animated Draw) */}
      <g style={{ opacity: 0.15, filter: 'blur(2px)' }}>
        <path
          d={archD}
          stroke="#FFFFFF"
          strokeWidth={glowStrokeWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
          className={animated ? 'logo-path-draw logo-path-delay-1' : ''}
        />
        <path
          d={crossD}
          stroke="#FFFFFF"
          strokeWidth={glowStrokeWidth}
          strokeLinecap="round"
          className={animated ? 'logo-path-draw logo-path-delay-2' : ''}
        />
      </g>

      {/* 4. Foreground: Symmetrical Monogram Paths (Animated Draw) with drop shadow */}
      <g style={{ filter: 'drop-shadow(0 1.5px 3px rgba(0, 0, 0, 0.45))' }}>
        {/* Symmetrical Arch */}
        <path
          d={archD}
          stroke={`url(#${uid}-mono)`}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
          className={animated ? 'logo-path-draw logo-path-delay-1' : ''}
        />
        {/* Symmetrical Crossbar */}
        <path
          d={crossD}
          stroke={`url(#${uid}-mono)`}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          className={animated ? 'logo-path-draw logo-path-delay-2' : ''}
        />
      </g>

      {/* 5. Animated Specular Shimmer Sweep Overlay */}
      {animated && (
        <g style={{ mixBlendMode: 'overlay', opacity: 0.95 }}>
          <rect
            x="8" y="8"
            width="84" height="84"
            rx="26"
            stroke={`url(#${uid}-shine)`}
            strokeWidth={badgeStrokeWidth + 0.5}
          />
          <path
            d={archD}
            stroke={`url(#${uid}-shine)`}
            strokeWidth={shineStrokeWidth}
            strokeLinecap="round"
            strokeLinejoin="round"
          />
          <path
            d={crossD}
            stroke={`url(#${uid}-shine)`}
            strokeWidth={shineStrokeWidth}
            strokeLinecap="round"
          />
        </g>
      )}
    </svg>
  );
};

export default Logo;
