'use client';

import { useEffect, useState } from 'react';
import Logo from '@/components/layout/Logo';

const LogoAnimation = () => {
  const [introComplete, setIntroComplete] = useState(false);
  const [showLogoText, setShowLogoText] = useState(false);

  useEffect(() => {
    // Elegant quick fade-in for logo
    const timer1 = setTimeout(() => {
      setShowLogoText(true);
    }, 150);

    // Complete the intro animation (adjusted to allow the slow cinematic drawing to complete)
    const timer2 = setTimeout(() => {
      setIntroComplete(true);
    }, 4800);

    return () => {
      clearTimeout(timer1);
      clearTimeout(timer2);
    };
  }, []);

  return (
    <div className={`intro-container ${introComplete ? 'intro-complete' : ''}`}>
      {/* Soft dark radial ambient background */}
      <div 
        className="absolute inset-0 opacity-90 pointer-events-none"
        style={{
          background: 'radial-gradient(circle, rgba(15, 15, 15, 0.7) 0%, rgba(0, 0, 0, 1) 100%)'
        }}
      />
      
      {/* Atmospheric breathing projection light projection behind the logo */}
      <div className="intro-backlight" />
      
      <div className="logo-container z-10">
        {showLogoText && (
          <Logo size={96} animated={true} />
        )}
      </div>
    </div>
  );
};

export default LogoAnimation;
